*/
char* get_target_for_redirect(const char* target, const char* domain) {
    // BEGIN SOLUTION
    char* result = malloc(strlen(target) + strlen(domain) + 10); // Extra space for "https://" and null
    char* target_netloc = get_netloc(target);

