        has_palette = 1;
        break;
    case 4:
    case 36:
        qtrle_decode_2n4bpp(s, stream_ptr, row_ptr, height, 4);
        has_palette = 1;
        break;
    case 8:
    case 40:
        qtrle_decode_8bpp(s, stream_ptr, row_ptr, height);
        has_palette = 1;
        break;
    case 16:
        qtrle_decode_16bpp(s, stream_ptr, row_ptr, height);
        break;
